/**
 * EzyCore Commerce - Combined Components Script
 * Menyatukan logika Shop View dan Product View untuk Alpine.js
 */

// 1. SHOP VIEW COMPONENT LOGIC
window.shopData = function () {
    return {
        products: [],
        categories: ["Semua"],
        activeCategory: "Semua",
        search: "",
        currentPage: 1,
        perPage: 12,
        isLoadingProducts: true,
        loadError: false,

        async init() {
            this.isLoadingProducts = true;
            try {
                var res = await fetch('/feeds/posts/default/-/product?alt=json&maxResults=500');
                var json = await res.json();
                if (json.feed && json.feed.entry) {
                    var parsed = [];
                    for (var i = 0; i < json.feed.entry.length; i++) {
                        try {
                            var entry = json.feed.entry[i];
                            var content = (entry.content && entry.content.$t) ? entry.content.$t : '';
                            var doc = new DOMParser().parseFromString(content, 'text/html');
                            var el = doc.querySelector('.ezy-meta');
                            if (!el) continue;
                            var d = JSON.parse((el.getAttribute('data-meta') || '{}').replace(/&apos;/g, "'"));

                            parsed.push({
                                id: d.id || '',
                                name: d.name || (entry.title ? entry.title.$t : '') || '',
                                slug: d.slug || '',
                                price: Number(d.price) || 0,
                                category: d.category || '',
                                image: d.image || '',
                                publishedat: d.publishedat || "",
                                _type: "product"
                            });
                        } catch (e) {
                            /* skip entry yang error */
                        }
                    }
                    this.products = parsed;

                    // Generate Kategori Unik
                    var catSet = {};
                    for (var ci = 0; ci < parsed.length; ci++) {
                        var pc = parsed[ci].category;
                        if (pc) catSet[pc] = true;
                    }
                    var cats = ["Semua"];
                    for (var ck in catSet) cats.push(ck);
                    this.categories = cats;
                }
                this.loadError = false;
            } catch (e) {
                console.warn("Shop fetch failed:", e);
                this.loadError = true;
            } finally {
                this.isLoadingProducts = false;
            }
        },

        get filteredProducts() {
            var result = this.products;
            if (this.activeCategory !== "Semua") {
                result = result.filter(function (p) {
                    return p.category === this.activeCategory;
                }.bind(this));
            }
            if (this.search.trim()) {
                var q = this.search.toLowerCase();
                result = result.filter(function (p) {
                    return p.name.toLowerCase().indexOf(q) !== -1 || p.category.toLowerCase().indexOf(q) !== -1;
                });
            }
            return result;
        },

        get paginatedProducts() {
            var start = (this.currentPage - 1) * this.perPage;
            return this.filteredProducts.slice(start, start + this.perPage);
        },

        get totalPages() {
            return Math.ceil(this.filteredProducts.length / this.perPage);
        }
    };
};

// 2. PRODUCT VIEW COMPONENT LOGIC
window.productViewData = function () {
    return {
        product: [],
        images: [],
        activeImage: 0,
        relatedProducts: [],

        async init() {
            // Mengambil metadata produk dari elemen jembatan global (jika ada)
            var meta = window._currentProductMeta;
            if (!meta) {
                // Fallback jika navigasi langsung / parsing DOM manual dari kontainer
                var el = document.querySelector('.ezy-meta');
                if (el) {
                    try {
                        meta = JSON.parse((el.getAttribute('data-meta') || '{}').replace(/&apos;/g, "'"));
                    } catch (e) { }
                }
            }
            if (!meta) return;

            this.product = meta;

            // Ambil array gambar dari metadata (mendukung string dipisah koma atau array langsung)
            if (meta.images) {
                this.images = Array.isArray(meta.images) ? meta.images : meta.images.split(',').map(function (s) { return s.trim(); });
            } else if (meta.image) {
                this.images = [meta.image];
            }
            this.activeImage = 0;

            // Ambil Produk Terkait (Related Products)
            var currentSlug = meta.slug || meta.id || '';
            try {
                var res = await fetch('/feeds/posts/default/-/product?alt=json&maxResults=500');
                var json = await res.json();
                if (json.feed && json.feed.entry) {
                    var parsed = [];
                    for (var i = 0; i < json.feed.entry.length; i++) {
                        try {
                            var entry = json.feed.entry[i];
                            var content = (entry.content && entry.content.$t) ? entry.content.$t : '';
                            var doc = new DOMParser().parseFromString(content, 'text/html');
                            var elRel = doc.querySelector('.ezy-meta');
                            if (!elRel) continue;
                            var d = JSON.parse((elRel.getAttribute('data-meta') || '{}').replace(/&apos;/g, "'"));

                            if (d._type !== 'product' || d.slug === currentSlug || d.id === currentSlug) continue;

                            parsed.push({
                                id: d.id || '',
                                name: d.name || (entry.title ? entry.title.$t : '') || '',
                                slug: d.slug || '',
                                price: Number(d.price) || 0,
                                category: d.category || '',
                                image: d.image || '',
                                publishedat: d.publishedat || ''
                            });
                        } catch (e) { }
                    }
                    this.relatedProducts = parsed.filter(function (p) {
                        return p.category === meta.category;
                    }).slice(0, 4);
                }
            } catch (e) {
                console.warn('Related products fetch failed:', e);
            }
        }
    };
};
